#include "core/Engine.h"
#include "core/FactoryPresets.h"
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <memory>
#include <set>
#include <vector>
using namespace cs80;
void undoCorrection(FactoryPreset& p) {
if (p.name == "Neon Brass 18") { p.values[86] = 0.379999995f; p.values[116] = 0.119999997f; }
if (p.name == "Velvet Strings 38") { p.values[86] = 0.219999999f; p.values[90] = 0.649999976f; p.values[116] = 0.159999996f; p.values[120] = 0.550000012f; }
if (p.name == "Neon Strings 40") { p.values[83] = 0.236599997f; p.values[86] = 0.219999999f; p.values[116] = 0.159999996f; }
if (p.name == "Dark FX 148") { p.values[73] = 132.300003f; p.values[86] = 0.660000026f; p.values[116] = 0.419999987f; }
if (p.name == "Sforzando Brass") { p.values[86] = 0.379999995f; p.values[116] = 0.119999997f; }
if (p.name == "Swell Strings") { p.values[86] = 0.219999999f; p.values[90] = 0.649999976f; p.values[116] = 0.159999996f; p.values[120] = 0.550000012f; }
if (p.name == "Spiccato Strings") { p.values[83] = 0.25999999f; p.values[86] = 0.219999999f; p.values[116] = 0.159999996f; }
if (p.name == "Clarinet") { p.values[86] = 0.310000002f; p.values[88] = 0.579999983f; p.values[90] = 0.360000014f; p.values[116] = 0.25f; p.values[118] = 0.75f; p.values[120] = 0.180000007f; }
if (p.name == "Bass Clarinet") { p.values[86] = 0.280000001f; p.values[88] = 0.639999986f; p.values[90] = 0.300000012f; p.values[116] = 0.239999995f; p.values[118] = 0.439999998f; p.values[120] = 0.219999999f; }
if (p.name == "Metallic Keys") { p.values[86] = 0.2667f; p.values[116] = 0.0975999981f; }
}
int main() {
    int rangeFailures=0; std::size_t checked=0;
    for (const auto& p:programLibrary()) for (int i=0;i<P_numParams;++i) {
      const auto& d=paramDef(i); const float x=p.values[i]; ++checked;
      if (!std::isfinite(x)||x<d.min||x>d.max) ++rangeFailures;
    }
    std::cout << "RANGE\t" << checked << "\t" << rangeFailures << '\n';
    const std::set<std::string> selected={"Swell Strings","Spiccato Strings","Clarinet","Bass Clarinet","Metallic Keys","Dark FX 148","Sforzando Brass"};
    constexpr int rate=48000, frames=105600;
    for(const auto& original:programLibrary()) {
      if(!selected.contains(original.name)) continue;
      for(bool corrected:{false,true}) for(int condition=0;condition<2;++condition) {
        auto p=original; if(!corrected) undoCorrection(p);
        const bool swell=p.name=="Swell Strings";
        const float velocity=swell?.8f:(condition==0?.3f:.85f);
        const float pressure=swell?static_cast<float>(condition):0.f;
        const int note=p.category=="Winds"?67:p.category=="Bells"?72:60;
        auto e=std::make_unique<Engine>();e->prepare(rate);e->setParams(p.values);
        e->noteOn(note,velocity,1);e->channelPressure(1,pressure);
        std::vector<float> block(512);double peak=0,energy[4]={};int counts[4]={};bool finite=true,released=false;
        for(int done=0;done<frames;done+=256) {
          if(!released && done>=72000){e->noteOff(note,1);released=true;}
          const int n=std::min(256,frames-done);e->render(block.data(),n);
          for(int i=0;i<n;++i) {
            const float l=block[2*i],r=block[2*i+1];finite=finite&&std::isfinite(l)&&std::isfinite(r);peak=std::max({peak,std::abs(double(l)),std::abs(double(r))});
            const double t=double(done+i)/rate,x=.5*(double(l)*l+double(r)*r);
            for(int w=0;w<4;++w){const double starts[]={.0,.30,.8,1.8},ends[]={.15,.60,1.20,2.2};if(t>=starts[w]&&t<ends[w]){energy[w]+=x;++counts[w];}}
          }
        }
        std::cout<<std::setprecision(10)<<p.name<<'\t'<<corrected<<'\t'<<velocity<<'\t'<<pressure<<'\t'<<finite<<'\t'<<20*std::log10(std::max(peak,1e-20));
        for(int w=0;w<4;++w)std::cout<<'\t'<<10*std::log10(std::max(energy[w]/counts[w],1e-40));std::cout<<'\n';
      }
    }
    return rangeFailures?1:0;
}
